// PALINDROME PARTITIONING II (#132) — O(n^2) time and space
function minCut(s) {
    const n = s.length;

    // Phase 1: build isPalin[i][j]
    const isPalin = Array.from({length: n}, () => new Array(n).fill(false));
    for (let i = 0; i < n; i++) isPalin[i][i] = true;
    for (let i = 0; i < n-1; i++) isPalin[i][i+1] = s[i] === s[i+1];
    for (let len = 3; len <= n; len++) {
        for (let i = 0; i <= n-len; i++) {
            const j = i+len-1;
            isPalin[i][j] = s[i] === s[j] && isPalin[i+1][j-1];
        }
    }

    // Phase 2: 1D cut DP
    // dp[i] = min cuts for s[0..i]
    const dp = new Array(n).fill(Infinity);
    for (let i = 0; i < n; i++) {
        if (isPalin[0][i]) {
            dp[i] = 0; // s[0..i] is itself a palindrome: 0 cuts
        } else {
            for (let j = 1; j <= i; j++) {
                if (isPalin[j][i]) {
                    dp[i] = Math.min(dp[i], dp[j-1] + 1);
                }
            }
        }
    }
    return dp[n-1];
}

console.log(minCut('aab'));    // 1 ('a' | 'ab' -> no... 'a' | 'a' | 'b' = 2? No: 'aa'+'b' = 1 cut)
console.log(minCut('a'));      // 0
console.log(minCut('ab'));     // 1
console.log(minCut('aabb'));   // 1 ('aa' + 'bb')

// SPACE-OPTIMISED: O(n) space using expand-around-centre
// Instead of isPalin table, expand inline during cut DP
function minCut_opt(s) {
    const n = s.length;
    const dp = Array.from({length: n+1}, (_,i) => i-1); // dp[i] = min cuts for s[0..i-1]
    // dp[0] = -1 (empty prefix, virtual base), dp[i] = i-1 (worst: cut every char)

    for (let centre = 0; centre < n; centre++) {
        // Odd-length palindromes
        for (let radius = 0; centre-radius >= 0 && centre+radius < n &&
             s[centre-radius] === s[centre+radius]; radius++) {
            dp[centre+radius+1] = Math.min(dp[centre+radius+1], dp[centre-radius] + 1);
        }
        // Even-length palindromes
        for (let radius = 1; centre-radius+1 >= 0 && centre+radius < n &&
             s[centre-radius+1] === s[centre+radius]; radius++) {
            dp[centre+radius+1] = Math.min(dp[centre+radius+1], dp[centre-radius+1] + 1);
        }
    }
    return dp[n];
}
