// HOUSE ROBBER III (#337) — tree DP with state vector
function rob(root) {
    function dfs(node) {
        if (!node) return [0, 0]; // [robThis, skipThis]
        const [leftRob, leftSkip]   = dfs(node.left);
        const [rightRob, rightSkip] = dfs(node.right);
        const robThis  = node.val + leftSkip + rightSkip; // rob: skip children
        const skipThis = Math.max(leftRob, leftSkip) + Math.max(rightRob, rightSkip);
        return [robThis, skipThis];
    }
    return Math.max(...dfs(root));
}

// BINARY TREE CAMERAS (#968) — greedy tree DP
// States: 0=not covered, 1=has camera, 2=covered (no camera)
function minCameraCover(root) {
    let cameras = 0;
    function dfs(node) {
        if (!node) return 2; // null node: pretend covered (no camera needed)
        const left = dfs(node.left);
        const right = dfs(node.right);

        if (left === 0 || right === 0) {
            cameras++; // child not covered: must place camera here
            return 1;
        }
        if (left === 1 || right === 1) {
            return 2; // child has camera: this node is covered
        }
        return 0; // both children covered: this node NOT covered, parent must cover
    }
    const rootState = dfs(root);
    if (rootState === 0) cameras++; // root uncovered: needs a camera
    return cameras;
}

// SUM OF DISTANCES IN TREE (#834) — re-rooting DP
function sumOfDistancesInTree(n, edges) {
    const adj = Array.from({length:n}, () => []);
    for (const [u,v] of edges) { adj[u].push(v); adj[v].push(u); }

    const count = new Array(n).fill(1); // subtree size
    const ans   = new Array(n).fill(0); // answer for each root

    // DFS 1: compute subtree sizes and ans[0] (distances from root 0)
    function dfs1(node, parent) {
        for (const child of adj[node]) {
            if (child === parent) continue;
            dfs1(child, node);
            count[node] += count[child];
            ans[node]   += ans[child] + count[child];
        }
    }
    // DFS 2: re-root: propagate from parent to children
    function dfs2(node, parent) {
        for (const child of adj[node]) {
            if (child === parent) continue;
            // Re-rooting: moving root from node to child:
            // distances increase by (n - count[child]) for all outside the subtree
            // distances decrease by count[child] for all inside the subtree
            ans[child] = ans[node] - count[child] + (n - count[child]);
            dfs2(child, node);
        }
    }
    dfs1(0, -1);
    dfs2(0, -1);
    return ans;
}

