// TRAVELLING SALESMAN PROBLEM (TSP) — bitmask DP
// O(2^n * n^2) time, O(2^n * n) space
function tsp(dist) {
    const n = dist.length;
    const FULL = (1 << n) - 1; // all cities visited
    const INF = Infinity;

    // dp[mask][i] = min cost to visit exactly cities in 'mask', ending at city i
    const dp = Array.from({length: 1 << n}, () => new Array(n).fill(INF));
    dp[1][0] = 0; // start at city 0 (mask=1 means only city 0 visited)

    for (let mask = 1; mask <= FULL; mask++) {
        for (let i = 0; i < n; i++) {
            if (dp[mask][i] === INF) continue;
            if (!(mask & (1 << i))) continue; // city i not in mask

            // Try extending to city j not yet visited
            for (let j = 0; j < n; j++) {
                if (mask & (1 << j)) continue; // already visited
                const nextMask = mask | (1 << j);
                dp[nextMask][j] = Math.min(dp[nextMask][j], dp[mask][i] + dist[i][j]);
            }
        }
    }

    // Return to start: complete the tour
    let minTour = INF;
    for (let i = 1; i < n; i++) { // start at 0, so end at i != 0
        if (dp[FULL][i] !== INF) {
            minTour = Math.min(minTour, dp[FULL][i] + dist[i][0]);
        }
    }
    return minTour;
}

