// Remove lowest bit:     mask & (mask - 1)

// SUBSET ENUMERATION: iterate all submasks of 'mask'
// Used in subset DP problems
function iterateSubmasks(mask) {
    const submasks = [];
    for (let sub = mask; sub > 0; sub = (sub-1) & mask) {
        submasks.push(sub);
    }
    submasks.push(0); // empty subset
    return submasks;
}

