// DIGIT DP TEMPLATE: count numbers in [0, N] with digit sum <= limit
function countWithDigitSum(N, limit) {
    const digits = String(N).split('').map(Number);
    const memo = new Map();

    function dp(pos, tight, currentSum) {
        // Base case: processed all digits
        if (pos === digits.length) return currentSum <= limit ? 1 : 0;

        const key = `${pos},${tight},${currentSum}`;
        if (memo.has(key)) return memo.get(key);

        const maxDigit = tight ? digits[pos] : 9;
        let count = 0;

        for (let d = 0; d <= maxDigit; d++) {
            const nextTight = tight && (d === maxDigit);
            count += dp(pos+1, nextTight, currentSum + d);
        }

        memo.set(key, count);
        return count;
    }
    return dp(0, true, 0); // start tight, sum = 0
}

