// COUNT NUMBERS WITH NO TWO CONSECUTIVE 1s (binary representation)
function countNoConsecutiveOnes(N) {
    const bits = N.toString(2).split('').map(Number);
    const memo = new Map();

    function dp(pos, tight, prevBit) {
        if (pos === bits.length) return 1;
        const key = `${pos},${tight},${prevBit}`;
        if (memo.has(key)) return memo.get(key);

        const maxBit = tight ? bits[pos] : 1;
        let count = 0;
        for (let bit = 0; bit <= maxBit; bit++) {
            if (prevBit === 1 && bit === 1) continue; // skip consecutive 1s
            count += dp(pos+1, tight && bit === maxBit, bit);
        }
        memo.set(key, count);
        return count;
    }
    return dp(0, true, 0);
}

