// KNIGHT PROBABILITY IN CHESSBOARD (#688)
// dp[r][c] = probability of being at (r,c) after k moves
// O(k * n^2) time, O(n^2) space (two rolling grids)
function knightProbability(n, k, row, column) {
    const MOVES = [[-2,-1],[-2,1],[-1,-2],[-1,2],[1,-2],[1,2],[2,-1],[2,1]];

    // Use two n x n grids: curr and next
    let curr = Array.from({length:n}, () => new Array(n).fill(0));
    curr[row][column] = 1.0; // start with probability 1 at initial position

    for (let move = 0; move < k; move++) {
        const next = Array.from({length:n}, () => new Array(n).fill(0));
        for (let r = 0; r < n; r++) {
            for (let c = 0; c < n; c++) {
                if (curr[r][c] === 0) continue;
                for (const [dr, dc] of MOVES) {
                    const nr = r+dr, nc = c+dc;
                    if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                        next[nr][nc] += curr[r][c] / 8.0; // 1/8 probability each move
                    }
                    // else: moved off board, probability lost
                }
            }
        }
        curr = next;
    }
    // Sum all remaining probabilities
    return curr.reduce((sum, row) => sum + row.reduce((s,v) => s+v, 0), 0);
}

