// NEW 21 GAME (#837) — probability DP with sliding window
// Player starts at 0, draws cards 1..maxPts each round until score >= n
// P(final score <= n + maxPts - 1)
function new21Game(n, k, maxPts) {
    if (k === 0 || n >= k + maxPts) return 1.0; // trivially all valid

    const dp = new Array(n + maxPts + 1).fill(0);
    dp[0] = 1.0;
    let windowSum = 1.0; // sliding window sum of dp[i-maxPts..i-1]
    let result = 0;

    for (let i = 1; i <= n + maxPts; i++) {
        dp[i] = windowSum / maxPts;
        if (i < k)  windowSum += dp[i];      // still drawing: add to window
        if (i >= k) result    += dp[i];       // stopped drawing: count towards answer
        if (i >= maxPts) windowSum -= dp[i - maxPts]; // remove expired from window
    }
    return result;
}
console.log(new21Game(10, 1, 10)); // 1.0 (draw one card 1-10, all <= 10+10-1=19)
console.log(new21Game(6, 1, 10));  // 0.6 (draw one card 1-10, 6 outcomes <= 6)

